mapper.select:
WITH T0 AS ( SELECT BOOKSET_ID
,BOOKSET_DATE
,to_date(#{booksetDate},'yyyy-MM-dd') BOOKSET_DATE
FROM BOK_BOOKSET_DATE ), T1 AS ( /**入账信息**/ SELECT S.BOOKSET_ID, S.START_DATE, S.END_DATE, S.BOOKSET_TYPE, C.BOOKSET_DATE, MIN(S.START_DATE) AS MINDATE, MIN(NVL(B.BOOK_DATE,C.BOOKSET_DATE)) AS MINBOOKDATE, DECODE(D.BOOKSET_ID_SON,NULL,'02','01') AS IS_SUB_BOOKSET FROM BOK_BOOKSET S INNER JOIN T0 C ON C.BOOKSET_ID = S.BOOKSET_ID AND C.BOOKSET_DATE >= S.START_DATE AND S.END_DATE >= C.BOOKSET_DATE LEFT JOIN BOK_DEAL_ACCOUNTING B ON B.BOOKSET_ID = S.BOOKSET_ID AND B.BOOKSET_DATE = C.BOOKSET_DATE LEFT JOIN BOK_BOOKSET_RE D ON D.BOOKSET_ID_SON = S.BOOKSET_ID
INNER JOIN BOK_DETAIL_ID E ON E.BOK_DETAIL_ID = B.BOK_DETAIL_ID AND E.BUSI_ID = #{busiId,jdbcType=VARCHAR}
WHERE 1=1 AND S.BOOKSET_TYPE = '02'
AND( S.BOOKSET_ID IN
#{item}
OR D.BOOKSET_ID IN
#{item}
)
GROUP BY S.BOOKSET_ID,S.BOOKSET_TYPE,C.BOOKSET_DATE,S.START_DATE,S.END_DATE,D.BOOKSET_ID_SON ), T2 AS ( /**日期**/ SELECT (MINDATE+ROWNUM-1) AS GDATE FROM( SELECT MAX(BOOKSET_DATE) MAXDATE, MIN(MINDATE) MINDATE FROM T1 )CONNECT BY (MAXDATE - MINDATE) >= ROWNUM -1 ), T3 AS ( /**入账日**/ SELECT T1.BOOKSET_ID, T1.BOOKSET_DATE, T1.START_DATE, T1.END_DATE, T1.BOOKSET_TYPE, T2.GDATE BOOK_DATE, MIN(NVL(B.HAPPEN_DATE,T2.GDATE)) MINHAPPENDATE, T1.IS_SUB_BOOKSET FROM T1 INNER JOIN T2 ON T1.BOOKSET_DATE >= T2.GDATE AND T2.GDATE >= T1.MINBOOKDATE LEFT JOIN BOK_DEAL_ACCOUNTING B ON B.BOOKSET_ID = T1.BOOKSET_ID AND B.BOOK_DATE = T2.GDATE GROUP BY T1.BOOKSET_ID, T1.BOOKSET_TYPE,T1.BOOKSET_DATE, T2.GDATE,T1.START_DATE,T1.END_DATE,T1.IS_SUB_BOOKSET )
SELECT T3.BOOK_DATE, T2.GDATE HAPPEN_DATE, T3.BOOKSET_ID, T3.BOOKSET_DATE, T3.START_DATE, T3.END_DATE, T3.BOOKSET_TYPE, E.BUSI_TYPE, E.BOK_DETAIL_ID, T3.IS_SUB_BOOKSET FROM T3 INNER JOIN T2 ON T3.BOOK_DATE >= T2.GDATE AND T2.GDATE >= T3.MINHAPPENDATE LEFT JOIN BOK_DEAL_ACCOUNTING B ON B.BOOKSET_ID = T3.BOOKSET_ID AND B.BOOK_DATE = T3.BOOK_DATE AND T2.GDATE >= B.HAPPEN_DATE LEFT JOIN BOK_DEAL_ACCOUNTING_DETAIL E ON B.BOOKSET_ID = E.BOOKSET_ID AND B.BUSI_NO = E.BUSI_NO AND B.BUSI_TABLE = E.BUSI_TABLE GROUP BY T3.BOOK_DATE, T2.GDATE, T3.BOOKSET_ID, T3.BOOKSET_DATE, T3.START_DATE, T3.END_DATE, T3.BOOKSET_TYPE, E.BUSI_TYPE, E.BOK_DETAIL_ID, T3.IS_SUB_BOOKSET ORDER BY T3.BOOK_DATE, T2.GDATE, T3.BOOKSET_ID, T3.BOOKSET_DATE
